param([Parameter(Mandatory)][string]$OutputPath,[string]$PlanPath=(Join-Path $PSScriptRoot 'numberformatinfo-clone-interface-plan-v1.json'))
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}
[Globalization.CultureInfo]::CurrentCulture=[Globalization.CultureInfo]::InvariantCulture;[Globalization.CultureInfo]::CurrentUICulture=[Globalization.CultureInfo]::InvariantCulture
$plan=Get-Content -LiteralPath $PlanPath -Raw|ConvertFrom-Json
function Decode($Spec,$Encoded){if([object]::ReferenceEquals($Encoded,$null)){$v=$null}elseif($Spec.kind -eq 'int'){$v=[int]$Encoded}elseif($Spec.kind -eq 'array'){$v=[int[]]$Encoded}else{$v=-join [char[]][int[]]$Encoded};return ,$v}
function New-Seed{$n=[Globalization.NumberFormatInfo]::new();foreach($spec in $plan.properties){[Globalization.NumberFormatInfo].GetProperty($spec.name).SetValue($n,(Decode $spec $spec.seed))};return $n}
function Snapshot($N){$values=[ordered]@{};foreach($spec in $plan.properties){$v=[Globalization.NumberFormatInfo].GetProperty($spec.name).GetValue($N);if($spec.kind -eq 'string'){$values[$spec.name]=[int[]][char[]]$v}elseif($spec.kind -eq 'array'){$values[$spec.name]=[int[]]$v}else{$values[$spec.name]=[int]$v}};return [ordered]@{readOnly=$N.IsReadOnly;values=$values}}
function Failure($Record){$e=$Record.Exception;while($e -is [Reflection.TargetInvocationException] -or $e -is [Management.Automation.MethodInvocationException]){$e=$e.InnerException};return [ordered]@{ok=$false;exception=$e.GetType().FullName;messageUnits=[int[]][char[]]$e.Message;hResult=$e.HResult;paramName=$(if($e -is [ArgumentException]){$e.ParamName}else{$null});actualValue=$(if($e -is [ArgumentOutOfRangeException]){$e.ActualValue}else{$null})}}

$nfiType=[Globalization.NumberFormatInfo];$first=$nfiType.GetInterfaces();$interfaces=@($first|ForEach-Object {$_.FullName});$second=$nfiType.GetInterfaces();$distinct=-not [object]::ReferenceEquals($first,$second);$first[0]=$null;$afterMutation=@($nfiType.GetInterfaces()|ForEach-Object {$_.FullName})
$lookups=[Collections.Generic.List[object]]::new();$lookupMethod=[type].GetMethod('GetInterface',[type[]]@([string],[bool]))
for($q=0;$q -lt $plan.queries.Count;$q++){foreach($ignore in @($false,$true)){try{$t=$lookupMethod.Invoke($nfiType,[object[]]@($plan.queries[$q],$ignore));$result=[ordered]@{ok=$true;name=$(if([object]::ReferenceEquals($t,$null)){$null}else{$t.FullName})}}catch{$result=Failure $_};$lookups.Add([ordered]@{query=$q;ignoreCase=$ignore;result=$result})}}
$assignments=[Collections.Generic.List[object]]::new();foreach($target in $plan.types){foreach($source in $plan.types){$a=[type]::GetType($target,$true);$s=[type]::GetType($source,$true);$assignments.Add([ordered]@{target=$target;source=$source;assignable=$a.IsAssignableFrom($s)})}}
$clones=[Collections.Generic.List[object]]::new()
foreach($mode in @('mutable','readonly','clone')){$original=New-Seed;$ro=[Globalization.NumberFormatInfo]::ReadOnly($original);if($mode -eq 'mutable'){$target=$original}elseif($mode -eq 'readonly'){$target=$ro}else{$target=[Globalization.NumberFormatInfo]$ro.Clone()};$clone=[Globalization.NumberFormatInfo][ICloneable].GetMethod('Clone').Invoke($target,[object[]]@());$clones.Add([ordered]@{mode=$mode;before=(Snapshot $target);clone=(Snapshot $clone);distinct=(-not [object]::ReferenceEquals($target,$clone));isInstance=[ICloneable].IsInstanceOfType($target);cloneIsInstance=[ICloneable].IsInstanceOfType($clone);cloneType=$clone.GetType().FullName})}
if($lookups.Count -ne 48 -or $assignments.Count -ne 49 -or $clones.Count -ne 3){throw 'Wrong clone interface matrix'}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();planSha256=(Get-FileHash -LiteralPath $PlanPath -Algorithm SHA256).Hash.ToLowerInvariant();culture='Invariant';interfaces=$interfaces;distinctInterfaces=$distinct;interfacesAfterMutation=$afterMutation;lookups=$lookups.ToArray();assignments=$assignments.ToArray();clones=$clones.ToArray();qualification='SELECTED_NUMBERFORMATINFO_ICLONEABLE_DISPATCH_AND_TYPE_RELATIONSHIPS_ONLY; OTHER_IMPLEMENTORS_ARRAY_STRING_BOXING_FULL_METADATA_CULTURE_SERIALIZATION_AND_TASK_ACCEPTANCE_OPEN'};[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 24 -Compress)+"`n",[Text.UTF8Encoding]::new($false));Write-Output 'PASS NumberFormatInfo clone interface: 48 lookups, 49 assignments and 3 dispatches'
